    -fx-font-weight: bold;
    -fx-background-radius: 8;
    -fx-cursor: hand;
}

.cancellaButton:hover {
    -fx-background-color: #5c1e1e;
}

/* ── Scroll bars ──────────────────────────────────────────── */
.scroll-bar:vertical .thumb,
.scroll-bar:horizontal .thumb {
    -fx-background-color: #9a9aa3;
    -fx-background-radius: 4;
}

.scroll-bar:vertical .track,
.scroll-bar:horizontal .track {
    -fx-background-color: #67696f;
}

/* ── CheckBox / RadioButton ───────────────────────────────── */
.check-box .text, .radio-button .text {
    -fx-text-fill: #f4e7e7;
}

.check-box .box {
    -fx-background-color: #67696f;
    -fx-border-color: #9a9aa3;
    -fx-border-radius: 3;
    -fx-background-radius: 3;
}

.check-box:selected .mark {
    -fx-background-color: #800303;
}

.radio-button .radio {
    -fx-background-color: #67696f;
    -fx-border-color: #9a9aa3;
}

.radio-button:selected .dot {
    -fx-background-color: #800303;
}

/* ── Separator ────────────────────────────────────────────── */
.separator .line {
    -fx-border-color: #9a9aa3;
}

/* ── Confirmation dialog overlay ─────────────────────────── */
.confirm-overlay {
    -fx-background-color: rgb(103, 105, 111);
}

.confirm-card {
    -fx-background-color: #67696f;
    -fx-border-color: #800303;
    -fx-border-width: 2;
    -fx-border-radius: 12;
    -fx-background-radius: 12;
    -fx-padding: 30;
    -fx-effect: dropshadow(gaussian, rgb(113, 99, 99), 24, 0, 0, 0);
}

.confirm-title {
    -fx-text-fill: #800303;
    -fx-font-size: 22px;
    -fx-font-weight: bold;
}

.confirm-detail {
    -fx-text-fill: #f4e7e7;
    -fx-font-size: 13px;
}

.confirm-code {
    -fx-text-fill: #f4e7e7;
    -fx-font-size: 16px;
    -fx-font-weight: bold;
    -fx-font-family: "Courier New", monospace;
    -fx-background-color: #0d1b2a;
    -fx-background-radius: 6;
    -fx-padding: 8 16 8 16;
}
